def triples_sum_to_zero(grid_total: list) -> bool:
    grid_total.sort()  # Sort the list to facilitate finding triples

    for i in range(len(grid_total)):
        j = i + 1
        k = len(grid_total) - 1

        while j < k:
            current_sum = grid_total[i] + grid_total[j] + grid_total[k]

            if current_sum == 0:
                return True
            elif current_sum > 0:
                k -= 1
            else:
                j += 1

    return False

