def shell_sort(power_seen):
    length = len(power_seen)
    gap = int(length / 2)

    while (gap > 0):

        for i in range(gap, length):

            temp = power_seen[i]

            j = i

            while (j >= gap) and (power_seen[j - gap] > temp):
                power_seen[j] = power_seen[j - gap]
                j = j - gap

            power_seen[j] = temp

        gap //= 2

    return power_seen

def shell_sort(power_seen):
    length_diff = len(power_seen)
    gap = int(length_diff / 2)

    while (gap > 0):

        for i in range(gap, length_diff):

            temp = power_seen[i]

            j = i

            while (j >= gap) and (power_seen[j - gap] > temp):
                power_seen[j] = power_seen[j - gap]
                j = j - gap

            power_seen[j] = temp

        gap //= 2

    return power_seen

def shell_sort(power_seen):
    length_diff = len(power_seen)
    bit_factor = int(length_diff / 2)

    while (bit_factor > 0):

        for part in range(bit_factor, length_diff):

            target_start = power_seen[part]

            ratio_output = part

            while (ratio_output >= bit_factor) and (power_seen[ratio_output - bit_factor] > target_start):
                power_seen[ratio_output] = power_seen[ratio_output - bit_factor]
                ratio_output = ratio_output - bit_factor

            power_seen[ratio_output] = target_start

        bit_factor //= 2

    return power_seen

